SELECT g, i, r, row_number() OVER (PARTITION BY g ORDER BY i, id), sum(r) OVER (ORDER BY id ROWS 3 PRECEDING), rank() OVER (ORDER BY i), lag(i) OVER (ORDER BY id), ntile(3) OVER (ORDER BY id) FROM t ORDER BY id;
